<?php foreach ($order['items'] as $item): ?><article><h2><?= $e($item['name']) ?></h2><p><?= $e($item['sku']) ?> · <?= $q($item['qty_milli']) ?> <?= $e($item['sell_unit']) ?> · <?= $m($item['line_total_minor']) ?></p></article><?php endforeach; ?>
<dl><?php foreach (['subtotal_minor'=>'Subtotal','discount_minor'=>'Discount','shipping_minor'=>'Delivery','tax_minor'=>'Tax','total_minor'=>'Total'] as $field=>$label): ?><dt><?= $e($label) ?></dt><dd><?= $m($order[$field]) ?></dd><?php endforeach; ?></dl>
<h2>Delivery address</h2><p><?= $e($order['address']['recipient']) ?><br><?= $e($order['address']['line1']) ?><br><?= $e($order['address']['line2']) ?><br><?= $e($order['address']['city'] . ', ' . $order['address']['state'] . ' ' . $order['address']['postal_code']) ?></p>
<section class="panel php-order-timeline"><h2>Order timeline</h2><ol><?php foreach ($order['history'] as $event): ?><li><strong><?= $e($event['to_status']) ?></strong> <time><?= $e(gmdate('d M Y H:i', (int)$event['created_at'])) ?> UTC</time><p><?= $e($event['reason']) ?></p></li><?php endforeach; ?></ol></section><p class="note">This is an order summary, not a tax invoice.</p><?php require __DIR__ . '/footer.php'; ?>
